from typing import List


def sort_numbers(numbers: str) -> str:
    word_to_num = {
        'zero': 0,
        'one': 1,
        'two': 2,
        'three': 3,
        'four': 4,
        'five': 5,
        'six': 6,
        'seven': 7,
        'eight': 8,
        'nine': 9
    }
    num_to_word = {v: k for k, v in word_to_num.items()}

    if not numbers:
        return ""

    words = numbers.split()
    sorted_words = sorted(words, key=lambda w: word_to_num[w])
    return " ".join(sorted_words)

from typing import List


def sort_numbers(numbers: str) -> str:
    word_to_num = {
        'zero': 0,
        'one': 1,
        'two': 2,
        'three': 3,
        'four': 4,
        'five': 5,
        'six': 6,
        'seven': 7,
        'eight': 8,
        'nine': 9
    }
    num_to_word = {v: k for k, v in word_to_num.items()}

    if not numbers.strip():
        return ""

    words = numbers.split()
    sorted_words = sorted(words, key=lambda w: word_to_num[w])
    return " ".join(sorted_words)

